using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using SistemaVentasMotorrepuestos.API.Datos;
using SistemaVentasMotorrepuestos.API.DTOs.Compras;
using SistemaVentasMotorrepuestos.API.Modelos;
using SistemaVentasMotorrepuestos.API.Servicios.Interfaces.Compras;

namespace SistemaVentasMotorrepuestos.API.Servicios.Implementaciones.Compras
{
    public class ProveedoresService : IProveedoresService
    {
        private readonly ApplicationDbContext _context;
        public ProveedoresService(ApplicationDbContext context) => _context = context;
        private static ProveedorDTO Map(Proveedor p, int count = 0, decimal total = 0) => new() { IdProveedor = p.IdProveedor, TipoDocumento = p.TipoDocumento, NumeroDocumento = p.NumeroDocumento, RazonSocial = p.RazonSocial, NombreComercial = p.NombreComercial, Direccion = p.Direccion, Telefono = p.Telefono, Correo = p.Correo, Estado = p.Estado, FechaCreacion = p.FechaCreacion, TotalCompras = count, TotalComprasMonto = total };
        private IQueryable<Proveedor> Filter(int empresa, ProveedorFiltroDTO f) => _context.Proveedores.AsNoTracking().Where(p => p.IdEmpresa == empresa).Where(p => string.IsNullOrWhiteSpace(f.Buscar) || p.NumeroDocumento.Contains(f.Buscar!) || p.RazonSocial.Contains(f.Buscar!) || p.NombreComercial.Contains(f.Buscar!) || p.Telefono.Contains(f.Buscar!)).Where(p => string.IsNullOrWhiteSpace(f.TipoDocumento) || p.TipoDocumento == f.TipoDocumento).Where(p => !f.Estado.HasValue || p.Estado == f.Estado.Value);
        public async Task<ProveedorPaginadoDTO> ListarAsync(int empresa, ProveedorFiltroDTO f) { f.PageNumber = f.PageNumber < 1 ? 1 : f.PageNumber; f.PageSize = f.PageSize is < 1 or > 100 ? 10 : f.PageSize; var q = Filter(empresa, f).OrderByDescending(p => p.FechaCreacion).ThenBy(p => p.IdProveedor); var total = await q.CountAsync(); var items = await q.Skip((f.PageNumber - 1) * f.PageSize).Take(f.PageSize).ToListAsync(); var ids = items.Select(p => p.IdProveedor).ToList(); var sums = await _context.Compras.AsNoTracking().Where(c => c.IdEmpresa == empresa && ids.Contains(c.IdProveedor) && c.Estado != "Anulada").GroupBy(c => c.IdProveedor).Select(g => new { Id = g.Key, Count = g.Count(), Total = g.Sum(c => c.Total) }).ToListAsync(); var map = sums.ToDictionary(x => x.Id); return new ProveedorPaginadoDTO { Items = items.Select(p => map.TryGetValue(p.IdProveedor, out var x) ? Map(p, x.Count, x.Total) : Map(p)).ToList(), PageNumber = f.PageNumber, PageSize = f.PageSize, TotalItems = total, TotalPages = (int)System.Math.Ceiling(total / (double)f.PageSize) }; }
        public async Task<IEnumerable<ProveedorDTO>> ObtenerProveedoresActivosAsync(int empresa) => (await ListarAsync(empresa, new ProveedorFiltroDTO { Estado = true, PageSize = 100 })).Items;
        public async Task<ProveedorDTO?> ObtenerProveedorPorIdAsync(int empresa, int id) { var p = await _context.Proveedores.AsNoTracking().FirstOrDefaultAsync(x => x.IdEmpresa == empresa && x.IdProveedor == id); if (p == null) return null; var cs = await _context.Compras.AsNoTracking().Where(c => c.IdEmpresa == empresa && c.IdProveedor == id && c.Estado != "Anulada").ToListAsync(); return Map(p, cs.Count, cs.Sum(c => c.Total)); }
        public async Task<ProveedorDTO> CrearAsync(int empresa, CrearProveedorDTO r) { var doc = r.NumeroDocumento.Trim(); if (string.IsNullOrWhiteSpace(doc) || string.IsNullOrWhiteSpace(r.RazonSocial)) throw new System.ArgumentException("Documento y razón social son obligatorios."); if (await _context.Proveedores.AnyAsync(p => p.IdEmpresa == empresa && p.TipoDocumento == r.TipoDocumento && p.NumeroDocumento == doc)) throw new System.InvalidOperationException("Ya existe un proveedor con ese documento."); var p = new Proveedor { IdEmpresa = empresa, TipoDocumento = r.TipoDocumento.Trim().ToUpperInvariant(), NumeroDocumento = doc, RazonSocial = r.RazonSocial.Trim(), NombreComercial = r.NombreComercial?.Trim() ?? string.Empty, Direccion = r.Direccion?.Trim() ?? string.Empty, Telefono = r.Telefono?.Trim() ?? string.Empty, Correo = r.Correo?.Trim() ?? string.Empty, Estado = true }; _context.Proveedores.Add(p); await _context.SaveChangesAsync(); return Map(p); }
        public async Task<ProveedorDTO> ActualizarAsync(int empresa, int id, ActualizarProveedorDTO r) { var p = await _context.Proveedores.FirstOrDefaultAsync(x => x.IdEmpresa == empresa && x.IdProveedor == id) ?? throw new KeyNotFoundException("Proveedor no encontrado."); p.TipoDocumento = r.TipoDocumento.Trim().ToUpperInvariant(); p.NumeroDocumento = r.NumeroDocumento.Trim(); p.RazonSocial = r.RazonSocial.Trim(); p.NombreComercial = r.NombreComercial?.Trim() ?? string.Empty; p.Direccion = r.Direccion?.Trim() ?? string.Empty; p.Telefono = r.Telefono?.Trim() ?? string.Empty; p.Correo = r.Correo?.Trim() ?? string.Empty; await _context.SaveChangesAsync(); return Map(p); }
        public async Task<ProveedorDTO> CambiarEstadoAsync(int empresa, int id, bool activo) { var p = await _context.Proveedores.FirstOrDefaultAsync(x => x.IdEmpresa == empresa && x.IdProveedor == id) ?? throw new KeyNotFoundException("Proveedor no encontrado."); p.Estado = activo; await _context.SaveChangesAsync(); return Map(p); }
        public async Task<IEnumerable<CompraDTO>> ObtenerComprasAsync(int empresa, int id) => await _context.Compras.AsNoTracking().Where(c => c.IdEmpresa == empresa && c.IdProveedor == id).OrderByDescending(c => c.FechaCompra).Select(c => new CompraDTO { IdCompra = c.IdCompra, NumeroCompra = c.NumeroCompra, FechaCompra = c.FechaCompra, Estado = c.Estado, Subtotal = c.Subtotal, Impuesto = c.Impuesto, Total = c.Total, Observaciones = c.Observaciones }).ToListAsync();
        public async Task<ProveedorEstadisticasDTO> ObtenerEstadisticasAsync(int empresa) { var ps = _context.Proveedores.AsNoTracking().Where(p => p.IdEmpresa == empresa); var cs = _context.Compras.AsNoTracking().Where(c => c.IdEmpresa == empresa && c.Estado != "Anulada"); return new ProveedorEstadisticasDTO { Total = await ps.CountAsync(), Activos = await ps.CountAsync(p => p.Estado), Inactivos = await ps.CountAsync(p => !p.Estado), ComprasRealizadas = await cs.CountAsync(), TotalCompras = await cs.SumAsync(c => (decimal?)c.Total) ?? 0 }; }
    }
}
